




-- Handbook v1.14 remediation: broad, realistic equipment/material catalogue with distinct constraints.
PRAGMA foreign_keys=OFF;
UPDATE products
SET product_id='PROD_INTERP_BLUETOOTH_HEADSET_03',
    title='translated business text（nonelinetranslated business textverify）',
    description='translated business textandtranslated business textline；nonelinetranslated business textmaytranslated business textequipment check，translated business texthasatofficialtranslated business textwiredtranslated business textfortranslated business text。'
WHERE product_id='PROD_INTERP_DIST_003';

WITH facts AS (
  SELECT rowid AS rid,
    CASE rowid % 17
      WHEN 0 THEN 'USB-A wiredheadset' WHEN 1 THEN '3.5 translated business textordertranslated business textheadset' WHEN 2 THEN 'translated business text' WHEN 3 THEN 'translated business text'
      WHEN 4 THEN 'USB-C adapter' WHEN 5 THEN 'headsetstoragetranslated business text' WHEN 6 THEN 'translated business text' WHEN 7 THEN 'backuptranslated business textline'
      WHEN 8 THEN 'interpretingshorthand notebook' WHEN 9 THEN 'translated business textlistening discriminationtranslated business text' WHEN 10 THEN 'officialtranslated business textprintingtranslated business text' WHEN 11 THEN 'translated business textitemtranslated business textfiletranslated business text'
      WHEN 12 THEN 'translated business textlinetranslated business text' WHEN 13 THEN 'translated business text' WHEN 14 THEN 'translated business text' WHEN 15 THEN 'translated business textcup'
      ELSE 'translated business textequipmenttranslated business text' END AS item_type,
    CASE rowid % 19
      WHEN 0 THEN 'translated business textandlaptopverify' WHEN 1 THEN 'translated business textwiredtranslated business text' WHEN 2 THEN 'translated business text' WHEN 3 THEN 'withouttranslated business text'
      WHEN 4 THEN 'translated business textordertranslated business text' WHEN 5 THEN 'translated business text' WHEN 6 THEN 'translated business textequipment' WHEN 7 THEN 'translated business textbackuptranslated business text'
      WHEN 8 THEN 'translated business textdaytranslated business textrefundable' WHEN 9 THEN 'translated business textaftertranslated business textrefundable' WHEN 10 THEN 'inventorytranslated business text' WHEN 11 THEN 'translated business textdaytranslated business text'
      WHEN 12 THEN 'translated business text' WHEN 13 THEN 'withouttrainingservice' WHEN 14 THEN 'translated business textpromisetranslated business text' WHEN 15 THEN 'purchasebeforetranslated business texthasequipment'
      WHEN 16 THEN 'translated business texttravelstorage' WHEN 17 THEN 'translated business textitem' ELSE 'translated business textbeforetranslated business textproducttranslated business text' END AS item_scope
  FROM products WHERE product_id LIKE 'PROD_INTERP_DIST_%'
)
UPDATE products
SET title=CASE rowid % 5
      WHEN 0 THEN (SELECT item_type || '｜' || item_scope FROM facts WHERE facts.rid=products.rowid)
      WHEN 1 THEN (SELECT item_scope || 'of' || item_type FROM facts WHERE facts.rid=products.rowid)
      WHEN 2 THEN (SELECT item_type || '（' || item_scope || '）' FROM facts WHERE facts.rid=products.rowid)
      WHEN 3 THEN (SELECT 'oral examandtravelsupplies：' || item_type || '；' || item_scope FROM facts WHERE facts.rid=products.rowid)
      ELSE (SELECT item_type || 'translated business text，' || item_scope FROM facts WHERE facts.rid=products.rowid)
    END,
    brand=CASE rowid % 7 WHEN 0 THEN 'translated business text' WHEN 1 THEN 'translated business text' WHEN 2 THEN 'translated business text' WHEN 3 THEN 'translated business text' WHEN 4 THEN 'translated business text' WHEN 5 THEN 'translated business textbefore' ELSE 'translated business text' END,
    category=CASE rowid % 6 WHEN 0 THEN 'translated business text' WHEN 1 THEN 'translated business textequipment' WHEN 2 THEN 'translated business textitem' WHEN 3 THEN 'translated business text' WHEN 4 THEN 'storage' ELSE 'translated business textsupplies' END,
    description=CASE rowid % 7
      WHEN 0 THEN (SELECT item_type || 'translated business textsessiontranslated business text；' || item_scope || '。' FROM facts WHERE facts.rid=products.rowid)
      WHEN 1 THEN (SELECT 'productis' || item_type || '。useboundary：' || item_scope || '。' FROM facts WHERE facts.rid=products.rowid)
      WHEN 2 THEN (SELECT item_scope || '；translated business textproducttranslated business text' || item_type || '，translated business textofficialtranslated business text。' FROM facts WHERE facts.rid=products.rowid)
      WHEN 3 THEN (SELECT 'translated business text' || item_type || '；' || item_scope || '，priceaccording to SKU prevails。' FROM facts WHERE facts.rid=products.rowid)
      WHEN 4 THEN (SELECT item_type || 'issimilarcandidate。translated business textitem：' || item_scope || '。' FROM facts WHERE facts.rid=products.rowid)
      WHEN 5 THEN (SELECT 'translated business text：' || item_type || '。translated business textthis' || item_scope || '。' FROM facts WHERE facts.rid=products.rowid)
      ELSE (SELECT 'fortranslated business text' || item_type || 'translated business text；' || item_scope || '。' FROM facts WHERE facts.rid=products.rowid)
    END,
    product_id=replace(product_id,'PROD_INTERP_DIST_','PROD_INTERP_CATALOG_')
WHERE product_id LIKE 'PROD_INTERP_DIST_%';

UPDATE stocks SET sku_id=replace(sku_id,'SKU_INTERP_DIST_','SKU_INTERP_CATALOG_') WHERE sku_id LIKE 'SKU_INTERP_DIST_%';
UPDATE skus
SET product_id=CASE WHEN product_id='PROD_INTERP_DIST_003' THEN 'PROD_INTERP_BLUETOOTH_HEADSET_03' ELSE replace(product_id,'PROD_INTERP_DIST_','PROD_INTERP_CATALOG_') END,
    sku_id=replace(sku_id,'SKU_INTERP_DIST_','SKU_INTERP_CATALOG_'),
    attrs_json=json_object(
      'connector',CASE rowid % 5 WHEN 0 THEN 'USB-C' WHEN 1 THEN 'USB-A' WHEN 2 THEN '3.5mm' WHEN 3 THEN 'dual_mode' ELSE 'not_applicable' END,
      'color',CASE rowid % 4 WHEN 0 THEN 'black' WHEN 1 THEN 'gray' WHEN 2 THEN 'blue' ELSE 'white' END,
      'warranty_months',CASE rowid % 3 WHEN 0 THEN 6 WHEN 1 THEN 12 ELSE 18 END
    )
WHERE sku_id LIKE 'SKU_INTERP_DIST_%';
PRAGMA foreign_keys=ON;

UPDATE skus
SET attrs_json=json_set(attrs_json,'$.catalog_item',(SELECT title FROM products WHERE products.product_id=skus.product_id))
WHERE sku_id LIKE 'SKU_INTERP_CATALOG_%';
